function sma(values, p) { return values.map((_,i) => i < p-1 ? NaN : values.slice(i-p+1,i+1).reduce((a,b)=>a+b,0)/p); }
function ema(values,p) { const out=Array(values.length).fill(NaN), k=2/(p+1); if(values.length<p)return out; out[p-1]=values.slice(0,p).reduce((a,b)=>a+b,0)/p; for(let i=p;i<values.length;i++)out[i]=values[i]*k+out[i-1]*(1-k); return out; }
