function atr(data,p=14) { const out=Array(data.length).fill(NaN); if(data.length<=p)return out; let s=0;for(let i=1;i<=p;i++)s+=Math.max(data[i].high-data[i].low,Math.abs(data[i].high-data[i-1].close),Math.abs(data[i].low-data[i-1].close));out[p]=s/p;for(let i=p+1;i<data.length;i++){const tr=Math.max(data[i].high-data[i].low,Math.abs(data[i].high-data[i-1].close),Math.abs(data[i].low-data[i-1].close));out[i]=(out[i-1]*(p-1)+tr)/p}return out; }
function metrics(data) { const closes=data.map(x=>x.close), e20=ema(closes,20),e50=ema(closes,50),e200=ema(closes,200),rs=rsi(closes), at=atr(data); const i=closes.length-1, macd=ema(closes,12)[i]-ema(closes,26)[i]; const basis=sma(closes,20)[i], sd=Math.sqrt(closes.slice(-20).reduce((s,x)=>s+(x-basis)**2,0)/20); const bb=(closes[i]-(basis-2*sd))/(4*sd||1); let score=0;score+=e20[i]>e50[i]?25:-25;score+=closes[i]>e50[i]?20:-20;score+=Number.isFinite(e200[i])?(closes[i]>e200[i]?20:-20):0;score+=Math.max(-15,Math.min(15,macd/(closes[i]*.0015)*15));score+=Math.max(-10,Math.min(10,(rs[i]-50)/2.5));score+=Math.max(-10,Math.min(10,(bb-.5)*20)); return { close:closes[i],e20:e20[i],e50:e50[i],e200:e200[i],rsi:rs[i],atr:at[i],macd,bb,score:Math.round(score) }; }
