function renderBacktest() { const d=state.candles;if(d.length<80){$('backtest').textContent='样本不足（至少 80 根 K 线）。';return}let pos=0,entry=0,profit=0,trades=0,wins=0;for(let i=50;i<d.length;i++){const sub=d.slice(Math.max(0,i-249),i+1),m=metrics(sub);if(!pos&&Math.abs(m.score)>=45){pos=Math.sign(m.score);entry=d[i].close}else if(pos&&Math.sign(m.score)!==pos){const ret=pos*(d[i].close-entry)/entry;profit+=ret;trades++;if(ret>0)wins++;pos=0}}$('backtest').innerHTML=[['已平仓交易',trades],['胜率',trades?(wins/trades*100).toFixed(2)+'%':'--'],['累计收益（未计成本）',(profit*100).toFixed(2)+'%'],['样本',`${d.length} 根 K 线`]].map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join(''); }
