function sigmoid(x){return 1/(1+Math.exp(-Math.max(-20,Math.min(20,x))))}
function featureSet(closes,i){const ret=k=>(closes[i]/closes[i-k]-1)*100;let mean=0;for(let k=1;k<=12;k++)mean+=ret(k);mean/=12;let variance=0;for(let k=1;k<=12;k++)variance+=(ret(k)-mean)**2;return [ret(1),ret(4),ret(12),Math.sqrt(variance/12)]}
function trainProbability(closes,horizon){const end=closes.length-horizon-1,rows=[];for(let i=20;i<=end;i+=3)rows.push({x:featureSet(closes,i),y:closes[i+horizon]>closes[i]?1:0});if(rows.length<80)return null;const split=Math.floor(rows.length*.8),train=rows.slice(0,split),test=rows.slice(split),w=[0,0,0,0],hidden=Array.from({length:6},(_,j)=>[.13*Math.sin(j+1),.11*Math.sin(j+3),.09*Math.sin(j+5),.07*Math.sin(j+7)]),out=Array.from({length:6},(_,j)=>.12*Math.cos(j+2));let bias=0,ob=0;for(let epoch=0;epoch<70;epoch++)for(const r of train){const z=r.x.map((_,j)=>r.x.reduce((s,v,k)=>s+v*hidden[j][k],0)),a=z.map(sigmoid),p=sigmoid(bias+r.x.reduce((s,v,j)=>s+v*w[j],0));const q=sigmoid(ob+a.reduce((s,v,j)=>s+v*out[j],0)),err=r.y-p;bias+=.012*err;r.x.forEach((v,j)=>w[j]+=.012*err*v);const qe=r.y-q;ob+=.008*qe;a.forEach((v,j)=>{out[j]+=.008*qe*v;hidden[j].forEach((_,k)=>hidden[j][k]+=.002*qe*out[j]*v*(1-v)*r.x[k])})}const score=r=>{const p=sigmoid(bias+r.x.reduce((s,v,j)=>s+v*w[j],0));const a=hidden.map(h=>sigmoid(r.x.reduce((s,v,k)=>s+v*h[k],0)));const q=sigmoid(ob+a.reduce((s,v,j)=>s+v*out[j],0));return (p+q)/2};const accuracy=test.filter(r=>(score(r)>=.5?1:0)===r.y).length/test.length;return {prob:score({x:featureSet(closes,closes.length-1)}),accuracy,train:train.length,test:test.length}}
async function loadForecasts(){const grid=$('forecastGrid'),status=$('forecastStatus');if(!grid)return;status.textContent='正在获取训练样本并进行滚动训练…';try{const r=await fetch('/api/forecast-history');const data=await r.json();if(!r.ok)throw new Error(data.error||'history request failed');const jobs=[['30分','intraday',2],['1小时','intraday',4],['2小时','intraday',8],['半天','intraday',48],['1天','intraday',96],['2天','intraday',192],['1周','daily',7],['半个月','daily',15],['1个月','daily',30],['半年','daily',180]];grid.innerHTML=jobs.map(([label,key,h])=>{const fit=trainProbability(data[key].map(x=>x.close),h);if(!fit)return `<div class="forecast-item muted"><span>${label}</span><b>样本不足</b></div>`;const long=fit.prob*100,cls=long>=50?'bull':'bear';return `<div class="forecast-item"><span>${label}</span><b class="${cls}">${long.toFixed(2)}% 看多</b><small>看空 ${(100-long).toFixed(2)}% · 验证 ${(fit.accuracy*100).toFixed(2)}% · n=${fit.train}</small></div>`}).join('');status.textContent=`双模型集成：L2 逻辑回归 + 小型神经网络 · ${data.cached?'缓存历史样本':'刚更新'} · 概率为方向条件概率，不是收益预测。`}catch(e){status.textContent=`概率模块暂不可用：${e.message}`}}
