function pearson(a,b){const n=Math.min(a.length,b.length),ma=a.slice(-n).reduce((s,x)=>s+x,0)/n,mb=b.slice(-n).reduce((s,x)=>s+x,0)/n;let xy=0,xx=0,yy=0;for(let i=0;i<n;i++){const x=a[a.length-n+i]-ma,y=b[b.length-n+i]-mb;xy+=x*y;xx+=x*x;yy+=y*y}return xy/Math.sqrt(xx*yy||1)}
