renderTicker = function(){const t=state.ticker;if(!t)return;const priceEl=$('price'),changeEl=$('change'),up=t.last>=t.open24h,delta=t.last-t.open24h,pulse=previousTickerPrice===null?(up?'price-up':'price-down'):(t.last>=previousTickerPrice?'price-up':'price-down');priceEl.textContent=money(t.last);changeEl.innerHTML=`<span class="change-amount">${delta>=0?'+':'−'}$${Math.abs(delta).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}</span><span class="change-pct">${pct(t.changePct)}</span><span class="price-market-meta"><small id="priceTime">${tx('实时','Live')} ${pointTime(Date.now())}</small></span>`;changeEl.className=up?'bull':'bear';[priceEl,changeEl].forEach(el=>{el.classList.remove('price-up','price-down');void el.offsetWidth;el.classList.add(pulse)});previousTickerPrice=t.last;$('open24').textContent=money(t.open24h);$('highlow').textContent=`${money(t.high24)} / ${money(t.low24)}`;$('sourceUsed').textContent=state.lastGood.source;}
loadCurrent = async function(){if(state.loading)return;state.loading=true;buttons();const started=performance.now();$('connection').textContent=tx('正在刷新行情…','Refreshing market…');$('chartError').hidden=true;try{const q=new URLSearchParams({interval:state.interval,limit:state.limit});if(state.source)q.set('source',state.source);const r=await apiFetch('/api/market?'+q);const data=await r.json();if(!r.ok)throw data;requestLatency=Math.round(performance.now()-started);state.candles=data.candles;state.ticker=data.ticker;state.lastGood=data;renderTicker();renderAnalysis();diagnostics(data);$('coverage').textContent=`${tx('图表覆盖','Chart coverage')}：${time(data.candles[0].time)} ${tx('至','to')} ${time(data.candles.at(-1).time)} · ${data.candles.length} ${tx('根','candles')} · ${tx('仅此范围参与回测','only this range is used in backtest')}`;$('connection').textContent=`${data.cached?tx('缓存行情','Cached quote'):tx('实时行情','Live quote')} · ${requestLatency} ms · ${tx('K线/指标每10秒更新；价格每秒刷新','Candles/indicators every 10s; quote every second')}`;$('freshness').textContent=pointTime(data.fetchedAt)}catch(e){$('connection').textContent=tx('行情暂不可用，保留最近成功数据','Market unavailable; keeping last successful data');$('chartError').hidden=false;$('chartError').textContent=`${tx('无法获取数据。','Could not fetch data. ')}${e.error||''}`;$('diagnostics').textContent=JSON.stringify(e.failures||e,null,2)}finally{state.loading=false}}
buttons = function(){const iLabel=tx('K 线周期','Candle interval'),rLabel=tx('查看范围','Visible range');$('intervals').innerHTML=`<span class="control-label">${iLabel}</span>`+intervals.map(([v,n])=>`<button data-i="${v}" class="${state.range===null&&state.interval===v?'active':''}">${uiLang==='zh'?n:v.replace('m','m').replace('h','h').replace('d','D')}</button>`).join('');$('ranges').innerHTML=`<span class="control-label">${rLabel}</span>`+Object.keys(ranges).map(x=>`<button data-r="${x}" class="${state.range===x?'active':''}">${x}</button>`).join('');document.querySelectorAll('[data-i]').forEach(b=>b.onclick=()=>{state.interval=b.dataset.i;state.limit=300;state.range=null;chartSelection=null;loadCurrent()});document.querySelectorAll('[data-r]').forEach(b=>b.onclick=()=>{const [i,l]=ranges[b.dataset.r];state.interval=i;state.limit=l;state.range=b.dataset.r;chartSelection=null;loadCurrent()})}
renderBacktest = function(){const d=state.candles;if(d.length<80){$('backtest').textContent=tx('样本不足（至少 80 根 K 线）。','Insufficient sample (at least 80 candles).');return}let pos=0,entry=0,profit=0,trades=0,wins=0;for(let i=50;i<d.length;i++){const m=metrics(d.slice(Math.max(0,i-249),i+1));if(!pos&&Math.abs(m.score)>=45){pos=Math.sign(m.score);entry=d[i].close}else if(pos&&Math.sign(m.score)!==pos){const ret=pos*(d[i].close-entry)/entry;profit+=ret;trades++;if(ret>0)wins++;pos=0}}$('backtest').innerHTML=[ [tx('已平仓交易','Closed trades'),trades],[tx('胜率','Win rate'),trades?(wins/trades*100).toFixed(2)+'%':'--'],[tx('累计收益（未计成本）','Cumulative return (pre-cost)'),(profit*100).toFixed(2)+'%'],[tx('样本','Sample'),`${d.length} ${tx('根 K 线','candles')}`] ].map(([k,v])=>`<div class="metric"><span>${k}</span><b>${v}</b></div>`).join('')}
