function renderFixedRuleSignal(){if(fixedRuleSignal.candles.length<200)return;const m=metrics(fixedRuleSignal.candles),[label,cls]=classification(m.score),signal=$('signal'),reason=$('signalReason');if(signal){signal.textContent=`${label} ${m.score>0?'+':''}${m.score.toFixed(2)}`;signal.className=`signal ${cls}`}if(reason)reason.innerHTML=`<span><b class="signal-indicator ${m.close>=m.e20?'bull':'bear'}">EMA20 ${money(m.e20)}</b><i>·</i><b class="signal-indicator ${m.close>=m.e50?'bull':'bear'}">EMA50 ${money(m.e50)}</b><i>·</i><b class="signal-indicator ${m.rsi>=50?'bull':'bear'}">RSI(14) ${m.rsi.toFixed(2)}</b><i>·</i><b class="signal-indicator ${m.macd>=0?'bull':'bear'}">MACD ${m.macd.toFixed(2)}</b></span>`;renderFixedIndicatorDetails(m);const sl=$('sl'),tp=$('tp');if(sl)sl.textContent=money(m.close-m.atr*1.5);if(tp)tp.textContent=money(m.close+m.atr*3);let basis=$('fixedRuleBasis');if(!basis&&reason){basis=document.createElement('small');basis.id='fixedRuleBasis';basis.className='fixed-rule-basis';reason.after(basis)}if(basis)basis.textContent=`${fixedRuleBasisText()} · 最近收盘 ${pointTime(fixedRuleSignal.closedAt)}`}
