(()=>{const card=$('signal')?.closest('article'),heading=card?.querySelector('h2');if(!card||!heading||$('fixedRuleControl'))return;const control=document.createElement('label');control.id='fixedRuleControl';control.className='fixed-rule-control';control.innerHTML=`<span>信号基准</span><select aria-label="信号基准周期"><option value="5m">5分钟</option><option value="15m">15分钟</option><option value="30m">30分钟</option><option value="1h">1小时</option><option value="3h">3小时</option></select>`;const select=control.querySelector('select');select.value=fixedRuleSignal.interval;select.onchange=()=>{fixedRuleSignal.interval=select.value;fixedRuleSignal.candles=[];fixedRuleSignal.closedAt=0;localStorage.setItem('btc_rule_signal_interval',select.value);loadFixedRuleSignal(true)};heading.after(control);$('source')?.addEventListener('change',()=>loadFixedRuleSignal(true));loadFixedRuleSignal(true);setInterval(()=>loadFixedRuleSignal(),15_000)})();
