function refreshDetailedIndicatorHelp(){const minutes={"1m":1,"5m":5,"15m":15,"30m":30,"1h":60,"2h":120,"4h":240,"1d":1440}[state.interval]||15,period=n=>{const total=n*minutes;return total<60?`${total} 分钟`:total<1440?`${(total/60).toFixed(total%60?1:0)} 小时`:`${(total/1440).toFixed(1)} 天`},tips={EMA20:`EMA20 看最近 20 根 ${state.interval} K 线（约 ${period(20)}），属于短线趋势参考。现价在 EMA20 上方通常偏强、下方偏弱；它会随当前周期改变。`,EMA50:`EMA50 看最近 50 根 ${state.interval} K 线（约 ${period(50)}），属于中短线趋势参考，比 EMA20 更平滑、反应更慢。现价上方偏强、下方偏弱。`,EMA200:`EMA200 看最近 200 根 ${state.interval} K 线（约 ${period(200)}），用于较长趋势背景。数据不足时显示 --；它不适合单独做超短线进场判断。`,'RSI(14)':`RSI(14) 衡量最近 14 根 ${state.interval} K 线（约 ${period(14)}）的涨跌动量，范围 0–100。约 70 以上常被视为偏热，约 30 以下常被视为偏弱；中间区域表示动量不明确，并非买卖指令。`,'布林位置':`布林位置表示当前价在布林带上下轨之间的相对位置：0% 靠近下轨，50% 接近中轨，100% 靠近上轨。它主要看价格位置与波动区间，不等于必然反转。`,'ATR(14)':`ATR(14) 是最近 14 根 ${state.interval} K 线（约 ${period(14)}）的平均真实波幅，单位是价格/美元。数值越大，说明每根 K 线平均波动越大；它用于估计止损、目标和风险，不判断涨跌方向。`};document.querySelectorAll('#indicators .metric:not([data-fixed-basis])').forEach(row=>{const label=row.querySelector('span')?.childNodes[0]?.textContent?.trim(),dot=row.querySelector('.help-dot');if(dot&&tips[label])dot.dataset.tip=tips[label]})}
