/* Empirical liquidation-risk calculator: uses 15-minute history and is not an exchange liquidation engine.
   经验强平风险计算器：使用 15 分钟历史数据，不替代交易所实际强平引擎。 */
const liqProbState=JSON.parse(localStorage.getItem('btc_liq_probability')||'{"exchange":"okx","side":"long","amount":1000,"leverage":10,"entry":0}');
let liqHistoricalCandles=[],liqHistoryLoading=false;
function liqTouchStats(candles,side,distance,horizon){let hits=0,total=0;for(let index=0;index+horizon<=candles.length;index++){const start=candles[index].close,segment=candles.slice(index,index+horizon),extreme=side>0?Math.min(...segment.map(candle=>candle.low)):Math.max(...segment.map(candle=>candle.high)),adverse=side>0?(start-extreme)/start:(extreme-start)/start;hits+=adverse>=distance?1:0;total++}return {hits,total,probability:total?hits/total*100:0}}
function liqRiskKind(probability){return probability>=25?'bear':probability>=10?'flat':'bull'}
// Reassign after legacy render hooks so this calculator remains the active implementation.
// 在旧版渲染钩子之后重新赋值，确保当前计算器实现保持生效。
calcLiqProbability=function(){
  const form=$('liqProbabilityForm'),out=$('liqProbabilityOutput');if(!form||!out)return;
  const p=liqProbState,livePrice=state.ticker?.last||state.candles.at(-1)?.close||0,rawEntry=Number(p.entry),entry=rawEntry>=10_000?rawEntry:livePrice,amount=Math.max(0,Number(p.amount)||0),lev=Math.min(100,Math.max(1,Math.round(Number(p.leverage)||1))),side=p.side==='short'?-1:1,mmr={binance:.004,okx:.005,coinbase:.006}[p.exchange]||.005,fee={binance:.0005,okx:.0005,coinbase:.0006}[p.exchange]||.0005;
  const liq=side>0?entry*(1-1/lev+mmr):entry*(1+1/lev-mmr),distance=Math.abs(liq-entry)/entry,history=liqHistoricalCandles.length>=100?liqHistoricalCandles:state.candles,extreme=history.length?(side>0?Math.min(...history.map(candle=>candle.low)):Math.max(...history.map(candle=>candle.high))):NaN;
  const horizons=[['12h',48],['24h',96],['48h',192],[tx('1 周','1 week'),672]].map(([label,window])=>({label,window,...liqTouchStats(history,side,distance,window)})),primary=horizons[0],level=liqRiskKind(primary.probability),direction=side>0?tx('做多','Long'):tx('做空','Short');
  if(rawEntry<10_000&&livePrice&&document.activeElement!==form.elements.entry){p.entry=livePrice;form.elements.entry.value=livePrice.toFixed(2);localStorage.setItem('btc_liq_probability',JSON.stringify(p))}
  if(String(lev)!==String(p.leverage)&&document.activeElement!==form.elements.leverage){p.leverage=lev;form.elements.leverage.value=lev;localStorage.setItem('btc_liq_probability',JSON.stringify(p))}
  const probabilityCards=horizons.map(item=>`<div><small>${item.label} ${tx('历史触及概率','historical touch')}</small><b class="${liqRiskKind(item.probability)}">${item.probability.toFixed(2)}%</b><em>n=${item.total}</em></div>`).join('');
  out.innerHTML=`<div><small>${tx('理论强平价','Theoretical liquidation')}</small><b class="bear">${money(liq)}</b></div><div><small>${tx('历史极值价格','Historical extreme price')}</small><b class="${side>0?'bear':'bull'}">${money(extreme)}</b></div><div><small>${tx('距成本价','Distance from entry')}</small><b>${(distance*100).toFixed(2)}%</b></div><div><small>${tx('手续费参考（开+平）','Fee reference (in + out)')}</small><b>${money(amount*fee*2)}</b></div>${probabilityCards}<p class="${level}">${direction} · ${tx('以成本价','Uses entry')} ${money(entry)} · ${lev}× · ${tx('使用','using')} ${history.length} ${tx('根 15 分钟历史 K 线的未来窗口统计；仅作风险研究，不代表未来真实概率或交易所强平价。','15-minute historical candles and forward-window counts; risk research only, not a future probability or an exchange liquidation price.')}</p>`;
};
