function renderSelectionOverlay(){if(!chartSelection)return;const d=visibleCandles(),a=Math.min(chartSelection.start,chartSelection.end),b=Math.max(chartSelection.start,chartSelection.end),s=d.slice(a,b+1),hi=Math.max(...s.map(v=>v.high)),lo=Math.min(...s.map(v=>v.low)),now=state.ticker?.last,ret=(s.at(-1).close/s[0].open-1)*100,overlay=$('selectionOverlay');if(!overlay||!Number.isFinite(now))return;const diff=(v)=>v-now;overlay.hidden=false;overlay.innerHTML=`<b>${tx('框选时间段','Selected range')}</b> ${pointTime(s[0].time)} — ${pointTime(s.at(-1).time)}<span>${tx('最高','High')} <em class="high">${money(hi)}</em> <i class="${diff(hi)>=0?'bull':'bear'}">${tx('较实时','vs live')} ${diff(hi)>=0?'+':'−'}${money(Math.abs(diff(hi)))}</i></span><span>${tx('最低','Low')} <em class="low">${money(lo)}</em> <i class="${diff(lo)>=0?'bull':'bear'}">${tx('较实时','vs live')} ${diff(lo)>=0?'+':'−'}${money(Math.abs(diff(lo)))}</i></span><span class="${ret>=0?'bull':'bear'}">${tx('区间涨跌','Range return')} ${pct(ret)}</span>`}
function resetResonanceTimer(){clearTimeout(resonanceTimer);resonanceTimer=setTimeout(async()=>{if(!document.hidden)await resonance(true);resetResonanceTimer()},10_000)}
resonance=async function(auto=false){const btn=$('loadResonance'),out=$('resonance');if(!out)return;if(!auto){btn.disabled=true;btn.textContent=tx('计算中…','Calculating…')}out.textContent=tx('正在计算 15m、1h、4h、1d 共振…','Calculating 15m, 1h, 4h and 1d resonance…');try{const rows=await Promise.all(['15m','1h','4h','1d'].map(async interval=>{const r=await fetch('/api/market?'+new URLSearchParams({interval,limit:200,source:state.source})),x=await r.json();if(!r.ok)throw new Error(`${interval}: ${x.error}`);const m=metrics(x.candles),[label,cls]=classification(m.score);return `<span class="res-chip ${cls}"><b>${interval}</b><em>${uiLang==='zh'?label:(cls==='bull'?'Bullish':cls==='bear'?'Bearish':'Neutral')} ${m.score>0?'+':''}${m.score.toFixed(2)}</em><small>${x.source}</small></span>`}));out.innerHTML=rows.join('')}catch(e){out.textContent=`${tx('共振计算失败','Resonance calculation failed')}：${e.message}`}finally{if(!auto){btn.disabled=false;btn.textContent=tx('重新计算共振','Recalculate resonance')}resetResonanceTimer()}};
function renderHorizonForecasts(){const host=$('microForecast');if(!host)return;let box=$('horizonForecasts');if(!box){box=document.createElement('div');box.id='horizonForecasts';box.className='horizon-forecasts';host.append(box)}if(!horizonForecastCache){box.innerHTML=`<span>${tx('正在训练 15 分钟与 24 小时模型…','Training 15m and 24h models…')}</span>`;return}const card=(label,fit)=>{const long=fit.prob*100,cls=long>=50?'bull':'bear';return `<article><small>${label}</small><b class="${cls}">${long.toFixed(2)}% ${tx('看多','bullish')}</b><span>${tx('看空','bearish')} ${(100-long).toFixed(2)}% · ${tx('历史验证','historical validation')} ${(fit.accuracy*100).toFixed(2)}%</span></article>`};box.innerHTML=card(tx('15 分钟机器预测','15m ML forecast'),horizonForecastCache.f15)+card(tx('24 小时长线预测','24h long-horizon forecast'),horizonForecastCache.f24)}
