function updateExtremaHover(event){const cv=$('chart'),d=visibleCandles(),high=$('rangeHighPoint'),low=$('rangeLowPoint');if(!cv||d.length<2||!high||!low)return;const rect=cv.getBoundingClientRect(),P={l:18,r:74,t:15,b:30},cw=rect.width-P.l-P.r,ch=rect.height-P.t-P.b,closes=d.map(v=>v.close),values=[...closes];[ema(closes,20),ema(closes,50),ema(closes,200)].forEach(a=>a.forEach(v=>{if(Number.isFinite(v))values.push(v)}));let min=Math.min(...values),max=Math.max(...values),pad=(max-min||1)*.075;min-=pad;max+=pad;const x=i=>P.l+i/(d.length-1)*cw,y=v=>P.t+ch-(v-min)/(max-min)*ch,hi=d.reduce((best,v,i)=>v.close>d[best].close?i:best,0),lo=d.reduce((best,v,i)=>v.close<d[best].close?i:best,0),mx=event.clientX-rect.left,my=event.clientY-rect.top,near=(i,v)=>Math.hypot(mx-x(i),my-y(v))<=15;high.classList.toggle('is-visible',near(hi,d[hi].close));low.classList.toggle('is-visible',near(lo,d[lo].close))}
