drawChartWithoutDuplicateExtremaText=function(){const proto=CanvasRenderingContext2D.prototype,fill=proto.fillText;proto.fillText=function(text,...args){if(typeof text==='string'&&(text.startsWith('最高选中价')||text.startsWith('最低选中价')||text.startsWith('Highest selected price')||text.startsWith('Lowest selected price')))return;const x=Number(args[0]),isTick=/^\d{2}\/\d{2}\s\d{2}:\d{2}$/.test(text);if(isTick){const previous=this.textAlign,canvasWidth=this.canvas.width/(devicePixelRatio||1);if(x<90){this.textAlign='left';args[0]=18}else if(x>canvasWidth-145){this.textAlign='right';args[0]=canvasWidth-74}const result=fill.call(this,text,...args);this.textAlign=previous;return result}return fill.call(this,text,...args)};try{drawCloseExtrema()}finally{proto.fillText=fill}};
