  const strength=Math.max(0,Math.min(100,Math.abs(m.score)||0));
  const atrPercent=Math.max(.05,(m.atr/Math.max(m.close,1))*100);
  const volatilityFactor=Math.max(.58,Math.min(1.16,.9/atrPercent));
  const expectedCandles=(1.55+strength/25)*volatilityFactor;
  const minMinutes=Math.max(candleMinutes,Math.round(candleMinutes*expectedCandles*.72));
  const maxMinutes=Math.max(minMinutes+candleMinutes,Math.round(candleMinutes*expectedCandles*1.36));
