function renderResearchOutlook(data){
  const card=ensureResearchOutlookCard();if(!card)return;
  const newsItems=(data.news?.items||[]).slice(0,6),newsRows=items=>items.map(item=>{const title=safeText(item.title),href=safeHref(item.url),category=safeText(item.category||'market');return `<li class="${item.sentiment>0?'bull':item.sentiment<0?'bear':'flat'}"><i>${item.sentiment>0?tx('利好','Positive'):item.sentiment<0?tx('利空','Negative'):tx('中性','Neutral')}</i>${href==='#'?`<span title="${title}">${title}</span>`:`<a href="${href}" target="_blank" rel="noopener noreferrer" title="${title}">${title}</a>`}<small>${safeText(item.source||'')} · ${category}</small></li>`}).join('')||`<li class="flat"><span>${tx('该时间窗暂无可用 BTC 新闻。','No BTC headline is available in this window.')}</span></li>`,twoHourItems=newsItems.filter(item=>Number.isFinite(item.publishedAt)&&Date.now()-item.publishedAt<=2*3_600_000),newsPanel=`<div class="research-news"><h3>${tx('BTC 重点新闻（可点击查看原文）','BTC priority headlines (click to open)')}</h3><div class="research-news-windows"><section><h4>${tx('近 2 小时','Last 2 hours')}</h4><ul>${newsRows(twoHourItems)}</ul></section><section><h4>${tx('近 24 小时','Last 24 hours')}</h4><ul>${newsRows(newsItems)}</ul></section></div></div>`,headlineRows=newsRows(newsItems);
  const windows=(data.windows||[]).map(window=>{const kind=researchDirectionClass(window.direction),move=Number(window.expectedMove),ret=Number(window.expectedReturn)*100,prob=Number(window.upProbability)*100,quality=Math.round(Number(window.matchQuality||0)*100),range=window.priceRange||{},isUp=prob>=50,directionProbability=isUp?prob:100-prob;return `<article class="research-window ${kind}"><span>${safeText(window.label)} · ${tx({bull:'牛市',bear:'熊市',range:'震荡'}[window.regime]||'未知',{bull:'Bull',bear:'Bear',range:'Range'}[window.regime]||'Unknown')}</span><b>${researchDirectionText(window.direction)}</b><strong class="${isUp?'bull':'bear'}">${isUp?tx('上涨','Up'):tx('下跌','Down')} · ${tx('概率','Probability')} ${directionProbability.toFixed(1)}%</strong><em>${tx('预期变动','Expected move')} ${move>=0?'+':'−'}${money(Math.abs(move))} (${ret>=0?'+':'−'}${Math.abs(ret).toFixed(2)}%)</em><small>${tx('价格区间 P10/P50/P90','Price range P10/P50/P90')}：${money(range.p10)} / ${money(range.p50)} / ${money(range.p90)}</small><small>${tx('匹配质量','Match quality')} ${quality}% · n=${window.samples}/${window.candidateCount}</small></article>`}).join('');
  const news=data.news||{},history=data.historical||{},sentiment=data.sentiment,derivatives=data.derivatives,eventRisk=data.eventRisk||[];
  const structuralTone=value=>!Number.isFinite(value)?'flat':value>0?'bull':value<0?'bear':'flat';
  const derivativeSummary=derivatives?`<div class="research-derivatives"><h3>${tx('市场结构（已纳入短期权重）','Market structure (included in short-horizon weight)')}</h3><div><span class="${structuralTone(derivatives.bookImbalancePct)}">${tx('盘口','Book')} <b>${Number.isFinite(derivatives.bookImbalancePct)?pct(derivatives.bookImbalancePct):'--'}</b></span><span class="${structuralTone(derivatives.takerImbalancePct)}">${tx('主动成交','Taker flow')} <b>${Number.isFinite(derivatives.takerImbalancePct)?pct(derivatives.takerImbalancePct):'--'}</b></span><span class="${structuralTone(derivatives.cvdSessionNotional)}">${tx('CVD（会话）','CVD (session)')} <b>${Number.isFinite(derivatives.cvdSessionNotional)?money(derivatives.cvdSessionNotional):'--'}</b></span><span class="${structuralTone(derivatives.oiChangePct)}">OI Δ <b>${Number.isFinite(derivatives.oiChangePct)?pct(derivatives.oiChangePct):'--'}</b></span><span class="flat">${tx('资金费率','Funding')} <b>${Number.isFinite(derivatives.fundingRate)?`${(derivatives.fundingRate*100).toFixed(4)}%`:'--'}</b></span></div><small>${tx('未接入','Not connected')}：${derivatives.unavailable.map(safeText).join(' · ')}</small></div>`:`<div class="research-derivatives unavailable"><h3>${tx('市场结构','Market structure')}</h3><small>${tx('OKX 微观结构暂不可用，本次预测未计入该层。','OKX microstructure is unavailable and is not included in this research run.')}</small></div>`;
  const eventBanner=eventRisk.length?`<div class="research-event-risk"><b>${tx('事件待定','Event pending')}</b><span>${safeText(eventRisk.join(' · '))} ${tx('将在 24 小时内公布：预测区间已应扩大解读。','is due within 24 hours: interpret forecast ranges more broadly.')}</span></div>`:'';
  // Scorecard combines chronological held-out validation with only settled live predictions; pending rows are never counted as hits.
  // 记分卡同时展示按时间保留的验证结果和已结算实时预测；未到期预测绝不会计入命中率。
  const scorecard=data.scorecard||{},scoreRows=(data.windows||[]).map(window=>{const live=scorecard.rows?.[window.key],pending=scorecard.pending?.[window.key]||0,validation=window.validation;return `<article><b>${safeText(window.label)}</b><span>${tx('验证','Validation')} ${validation?`${(validation.accuracy*100).toFixed(1)}% · Brier ${validation.brier.toFixed(3)} · n=${validation.samples}`:tx('样本不足','Insufficient samples')}</span><span>${live?`${tx('实时命中','Live hit')} ${(live.hitRate*100).toFixed(1)}% · Brier ${live.brier.toFixed(3)} · n=${live.settled}`:`${tx('实时命中待积累','Live outcomes pending')} · ${tx('待结算','Pending')} ${pending}`}</span></article>`}).join('');
  const scorecardPanel=`<section class="research-scorecard"><h3>${tx('模型记分卡','Model scorecard')}</h3><p>${tx('融合：历史近邻 55% + 时间顺序逻辑模型 45%，再叠加新闻、情绪与 OKX 结构；概率以保留样本进行 Platt 校准，并对孤立周期做一致性收缩。','Fusion: 55% historical neighbors + 45% time-ordered logistic model, then news, sentiment and OKX structure; probabilities use held-out Platt calibration and an isolated-horizon consistency guard.')}</p><div>${scoreRows}</div></section>`;
  card.innerHTML=`<div class="research-outlook-head"><div><h2>${tx('BTC 多因子研究预测','BTC multi-factor research outlook')}</h2><p>${tx('软加权历史近邻数据模型融合历史状态、近 24 小时公开 BTC 新闻情绪与 OKX 市场结构；结果为条件概率与价格区间，不是买卖建议。','A soft-weighted historical-neighbor data model combines historical states, recent public BTC news sentiment, and OKX market structure. Results are conditional probabilities and price ranges, not buy/sell advice.')}</p></div><button type="button" id="refreshResearchOutlook">${tx('更新研究','Refresh research')}</button></div>${eventBanner}<div class="research-outlook-summary"><span>${tx('新闻情绪','News sentiment')}：<b class="bull">${news.bullish||0} ${tx('利好','positive')}</b> · <b class="bear">${news.bearish||0} ${tx('利空','negative')}</b> · <b class="flat">${news.neutral||0} ${tx('中性','neutral')}</b> · ${tx('半衰期','half-life')} ${news.halfLifeHours||4}h</span><span>${tx('情绪指数','Fear & Greed')}：<b>${Number.isFinite(sentiment?.value)?`${sentiment.value}/100`:'--'}</b></span><span>${tx('中性阈值','Neutral band')}：44–56%</span><span>${tx('样本','Samples')}：15m ${history.intradaySamples||0} · 1d ${history.dailySamples||0}</span></div><div class="research-window-grid">${windows}</div>${derivativeSummary}<div class="research-news"><h3>${tx('近期 BTC 重点新闻（可点击查看原文）','Priority BTC headlines (click to open)')}</h3><ul>${headlineRows}</ul></div><footer>${tx('更新时间','Updated')} ${researchAge(data.fetchedAt)} · ${safeText(news.source||'')} · ${tx('新闻优先按利好/利空影响排序，并采用标题相似度去重、信源与事件权重、4 小时时间衰减；仍需自行核验其真实性与影响。','Headlines prioritize positive/negative impact, with similarity dedupe, source/event weights, and a 4-hour time decay; verify accuracy and impact independently.')}</footer>`;
  const legacyNews=card.querySelector('.research-news');if(legacyNews)legacyNews.outerHTML=newsPanel;
  card.querySelector('.research-derivatives')?.insertAdjacentHTML('afterend',scorecardPanel);
  card.querySelector('#refreshResearchOutlook')?.addEventListener('click',()=>loadResearchOutlook(true));
  addHelp(card.querySelector('h2'),tx('模型从本机 SQLite 与公开行情中使用所有可用的 15 分钟、日线历史样本，寻找与当前动量和波动接近的历史片段；新闻仅对结果施加有限权重。预计金额是 BTC 价格变动（美元），不是你的账户盈亏。','The model uses all available 15-minute and daily samples in local SQLite/public market history to find past states similar in momentum and volatility. News has limited weight only. Expected amount is the BTC price move in USD, not your account P&L.'),tx('刷新会重新读取缓存/公开数据源；公开新闻源最多每 15 分钟更新一次。','Refreshes cache/public sources; the public news source updates at most every 15 minutes.'));
}
async function loadResearchOutlook(force=false){
  if(researchOutlookLoading)return;researchOutlookLoading=true;
  const card=ensureResearchOutlookCard();
  if(card&&!card.innerHTML)card.innerHTML=`<div class="research-outlook-head"><div><h2>${tx('BTC 多因子研究预测','BTC multi-factor research outlook')}</h2><p>${tx('正在读取历史样本、公开新闻与市场结构…','Reading history samples, public news, and market structure…')}</p></div></div>`;
  try{const response=await apiFetch(`/api/research-outlook${force?'?refresh=1':''}`,20_000),data=await response.json();if(!response.ok)throw new Error(data.detail||data.error||'request failed');renderResearchOutlook(data)}
  catch(error){if(card)card.innerHTML=`<div class="research-outlook-head"><div><h2>${tx('BTC 多因子研究预测','BTC multi-factor research outlook')}</h2><p class="bear">${tx('研究数据暂不可用：','Research data unavailable: ')}${safeText(error.message)}</p></div><button type="button" id="refreshResearchOutlook">${tx('重试','Retry')}</button></div>`;card?.querySelector('#refreshResearchOutlook')?.addEventListener('click',()=>loadResearchOutlook(true))}
  finally{researchOutlookLoading=false}
}
setTimeout(()=>loadResearchOutlook(),2_500);
setInterval(()=>loadResearchOutlook(),900_000);

/* Keep the first time label wholly inside the plot after the left scale has
   been widened for readable price labels. */
drawChartWithoutDuplicateExtremaText=function(){
  const proto=CanvasRenderingContext2D.prototype,fill=proto.fillText;
  proto.fillText=function(text,...args){
    if(typeof text==='string'&&(text.startsWith('最高选中价')||text.startsWith('最低选中价')||text.startsWith('Highest selected price')||text.startsWith('Lowest selected price')))return;
    const x=Number(args[0]),isTick=/^\d{2}\/\d{2}\s\d{2}:\d{2}$/.test(text);
    if(isTick){
      const previous=this.textAlign,canvasWidth=this.canvas.width/(devicePixelRatio||1);
      if(x<105){this.textAlign='left';args[0]=52}
      else if(x>canvasWidth-145){this.textAlign='right';args[0]=canvasWidth-74}
      const result=fill.call(this,text,...args);this.textAlign=previous;return result;
    }
    return fill.call(this,text,...args);
  };
  try{drawCloseExtrema()}finally{proto.fillText=fill}
};

/* The changelog follows the version pill, rather than using a fixed viewport
   corner that drifts away when the header is centered or resized. */
$('appVersion')?.addEventListener('click',()=>{
  requestAnimationFrame(()=>{
    const version=$('appVersion'),log=$('versionChangelog');
    if(!version||!log||log.hidden)return;
    const rect=version.getBoundingClientRect(),width=Math.min(340,innerWidth-28);
    log.style.top=`${rect.bottom+8}px`;
    log.style.left=`${Math.max(14,Math.min(innerWidth-width-14,rect.left))}px`;
    log.style.right='auto';
  });
});
